"use strict";(globalThis.webpackChunkalova_website=globalThis.webpackChunkalova_website||[]).push([[8686],{60398(a){a.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/react-query-bff-gap","metadata":{"permalink":"/zh-CN/blog/react-query-bff-gap","source":"@site/i18n/zh-CN/docusaurus-plugin-content-blog/2026-08-05-react-query-bff-gap.md","title":"react-query \u7ba1\u4e0d\u5230 BFF\uff1falova/server \u8865\u4e0a\u91cd\u8bd5\u9650\u6d41","description":"react-query \u7684\u91cd\u8bd5\u548c\u7f13\u5b58\u90fd\u5728\u6d4f\u89c8\u5668\u91cc\u3002\u4f60\u7684 BFF \u8c03\u4e0b\u6e38\u670d\u52a1\u7684\u51fa\u7ad9\u8c03\u7528\u8dd1\u5728\u670d\u52a1\u7aef\uff0creact-query \u591f\u4e0d\u5230\u3002\u8fd9\u7bc7\u5212\u6e05\u90a3\u6761\u7ebf\uff0c\u5e76\u7ed9\u51fa\u4e24\u4fa7\u4ee3\u7801\u3002","date":"2026-08-05T00:00:00.000Z","tags":[{"inline":true,"label":"react-query","permalink":"/zh-CN/blog/tags/react-query"},{"inline":true,"label":"bff","permalink":"/zh-CN/blog/tags/bff"},{"inline":true,"label":"alova-server","permalink":"/zh-CN/blog/tags/alova-server"},{"inline":true,"label":"\u91cd\u8bd5","permalink":"/zh-CN/blog/tags/\u91cd\u8bd5"},{"inline":true,"label":"\u9650\u6d41","permalink":"/zh-CN/blog/tags/\u9650\u6d41"}],"readingTime":3.44,"hasTruncateMarker":false,"authors":[{"name":"Alova Team","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"/react-query-bff-gap","title":"react-query \u7ba1\u4e0d\u5230 BFF\uff1falova/server \u8865\u4e0a\u91cd\u8bd5\u9650\u6d41","authors":[{"name":"Alova Team"}],"tags":["react-query","bff","alova-server","\u91cd\u8bd5","\u9650\u6d41"],"date":"2026-08-05T00:00:00.000Z","description":"react-query \u7684\u91cd\u8bd5\u548c\u7f13\u5b58\u90fd\u5728\u6d4f\u89c8\u5668\u91cc\u3002\u4f60\u7684 BFF \u8c03\u4e0b\u6e38\u670d\u52a1\u7684\u51fa\u7ad9\u8c03\u7528\u8dd1\u5728\u670d\u52a1\u7aef\uff0creact-query \u591f\u4e0d\u5230\u3002\u8fd9\u7bc7\u5212\u6e05\u90a3\u6761\u7ebf\uff0c\u5e76\u7ed9\u51fa\u4e24\u4fa7\u4ee3\u7801\u3002","keywords":["react-query bff","alova server \u91cd\u8bd5","alova server \u9650\u6d41","bff \u91cd\u8bd5 react-query"]},"unlisted":false,"nextItem":{"title":"\u4f60\u7684 BFF \u88ab\u9650\u6d41\u6253\u6302\uff0c\u52a0\u4e00\u5c42\u91cd\u8bd5\u5c31\u597d","permalink":"/zh-CN/blog/bff-retry"}},"content":"\u4f60\u7528 react-query \u642d\u4e86\u524d\u7aef\uff0c\u5b83\u7684\u7f13\u5b58\u548c\u91cd\u8bd5\u8ba9\u6d4f\u89c8\u5668\u90a3\u8fb9\u5f88\u987a\u3002\u540e\u6765\u4f60\u8d77\u4e86\u4e2a Node BFF \u8c03\u4e09\u4e2a\u4e0b\u6e38\u670d\u52a1\uff0c\u8fd9\u4e9b\u8c03\u7528\u7684\u91cd\u8bd5\u548c\u9650\u6d41\u90fd\u843d\u5728\u670d\u52a1\u7aef\uff0c\u800c react-query \u5728\u90a3\u513f\u6839\u672c\u4e0d\u8dd1\u3002\u8fd9\u7bc7\u5212\u6e05 react-query \u7684\u5de5\u4f5c\u6b62\u6b65\u4e8e\u54ea\u3001alova/server \u4ece\u54ea\u63a5\u624b\uff0c\u5e76\u7ed9\u51fa\u4e24\u4fa7\u7684\u4ee3\u7801\u3002\\n\\n## \u90a3\u6761\u7ebf\\n\\nreact-query \u6d3b\u5728\u6d4f\u89c8\u5668\u91cc\u3002\u5b83\u7684 `useQuery` \u91cd\u8bd5\u3001\u7f13\u5b58\u3001\u53bb\u91cd\uff0c\u5168\u90fd\u53d1\u751f\u5728\u6bcf\u4e2a\u6d4f\u89c8\u5668\u6807\u7b7e\u9875\u91cc\uff0c\u7ed1\u7740 React \u7684\u6e32\u67d3\u5468\u671f\u3002\u5f53\u4f60\u7684 BFF \u8c03\u4e0b\u6e38\u65f6\uff0c\u8fd9\u4e9b\u903b\u8f91\u5728 BFF \u5185\u90e8\u4e00\u4e2a\u90fd\u4e0d\u6267\u884c\u3002\u6240\u4ee5\u95ee\u9898\u4e0d\u662f\u300creact-query \u8fd8\u662f alova\u300d\uff0c\u800c\u662f\u300c\u670d\u52a1\u7aef\u90a3\u5c42\u8c03\u7528\u5f52\u8c01\u7ba1\u300d\u3002\\n\\n## \u91cd\u8bd5\uff1a\u6d4f\u89c8\u5668 vs BFF\\n\\nreact-query \u5728\u6d4f\u89c8\u5668\u91cc\u91cd\u8bd5\u4e00\u4e2a\u5931\u8d25\u7684\u67e5\u8be2\uff1a\\n\\n```js\\nuseQuery({\\n  queryKey: [\'resource\', id],\\n  queryFn: () => fetch(`/api/resource/${id}`).then(r => r.json()),\\n  retry: 3,\\n  retryDelay: attempt => Math.min(1000 * 2 ** attempt, 8000)\\n});\\n```\\n\\n\u8fd9\u4e2a\u91cd\u8bd5\u62a4\u7684\u662f\u7528\u6237\u7684\u89c6\u56fe\u3002\u5b83\u5bf9 BFF \u51fa\u7ad9\u8c03\u4e0b\u6e38\u6beb\u65e0\u4f5c\u7528\uff0c\u56e0\u4e3a\u90a3\u6b21\u8c03\u7528\u538b\u6839\u4e0d\u7ecf\u8fc7 react-query\u3002\\n\\n\u5728 BFF \u4e0a\uff0calova/server \u5bf9\u51fa\u7ad9\u8bf7\u6c42\u505a\u9000\u907f\u91cd\u8bd5\uff1a\\n\\n```js\\nconst { createAlova } = require(\'alova\');\\nconst { axiosRequestAdapter } = require(\'@alova/adapter-axios\');\\nconst { retry } = require(\'alova/server\');\\n\\nconst alovaInst = createAlova({\\n  baseURL: \'https://downstream.internal\',\\n  requestAdapter: axiosRequestAdapter()\\n});\\n\\nconst getResource = (id) =>\\n  retry(alovaInst.Get(`/resource/${id}`), {\\n    retry: 5,\\n    backoff: { delay: 1000, multiplier: 2 }\\n  });\\n\\n// \u5728\u8def\u7531 handler \u91cc\uff1a\\nconst data = await getResource(req.params.id);\\n```\\n\\n\u540c\u4e00\u4e2a\u601d\u8def\uff0c\u4e0d\u540c\u5c42\u3002react-query \u7ba1\u6d4f\u89c8\u5668\uff0c`retry` \u7ba1\u670d\u52a1\u7aef\u3002\u987a\u5e26\u4e00\u53e5\uff1aalova \u7684\u5ba2\u6237\u7aef hook \u5728 uni-app / Taro / \u5c0f\u7a0b\u5e8f\u91cc\u4e5f\u80fd\u8dd1\u540c\u4e00\u5957 `useRequest`\uff0c\u6240\u4ee5\u300c\u6d4f\u89c8\u5668/\u670d\u52a1\u7aef\u5206\u5c42\u300d\u5728\u5185\u5ba2\u6237\u7aef\u4e5f\u6210\u7acb\u3002\\n\\n## \u9650\u6d41\uff1a\u53ea\u5728\u670d\u52a1\u7aef\u6709\\n\\nreact-query \u5b8c\u5168\u6ca1\u6709\u300c\u7ed9 BFF \u8c03\u4e0b\u6e38\u505a\u9650\u6d41\u300d\u8fd9\u4e2a\u6982\u5ff5\uff0c\u5b83\u7684 API \u91cc\u627e\u4e0d\u5230\u300c\u5bf9\u670d\u52a1 X \u6bcf\u79d2\u6700\u591a 4 \u6b21\u300d\u8fd9\u79cd\u4e1c\u897f\u3002\u90a3\u662f\u670d\u52a1\u7aef\u7684\u4e8b\uff0c\u800c alova/server \u7684 `createRateLimiter` \u6b63\u662f\u4e3a\u5b83\u751f\u7684\uff1a\\n\\n```js\\nconst { createRateLimiter } = require(\'alova/server\');\\n\\nconst rateLimit = createRateLimiter({ duration: 4000, points: 4 });\\n\\napp.get(\'/api/resource/:id\', async (req, res) => {\\n  try {\\n    const data = await rateLimit(\\n      retry(alovaInst.Get(`/resource/${req.params.id}`), {\\n        retry: 5,\\n        backoff: { delay: 1000, multiplier: 2 }\\n      }),\\n      { key: `downstream:${req.params.id}` }\\n    );\\n    res.json(data);\\n  } catch (err) {\\n    res.status(429).json({ error: \'downstream busy, retry later\' });\\n  }\\n});\\n```\\n\\n`rateLimit` \u5728\u8bf7\u6c42\u771f\u6b63\u51fa\u53bb\u4e4b\u524d\u5148\u6263\u4e00\u4e2a\u70b9\uff0c\u88ab\u4e0b\u6e38\u6253\u8db4\u7684\u65f6\u5019\u5b83\u4e0d\u88ab\u4f60\u81ea\u5df1\u7684\u6d41\u91cf\u57cb\u4e86\u3002\u9ed8\u8ba4\u5b58\u50a8\u662f method \u7684 `l2Cache`\uff1b\u8de8\u5b9e\u4f8b\u65f6\u4f60\u6362\u6210\u4e00\u4e2a\u5171\u4eab\u5b58\u50a8\uff08`@alova/psc` \u6216 redis\uff09\uff0c\u989d\u5ea6\u624d\u662f\u771f\u6b63\u96c6\u7fa4\u7ea7\u7684\u3002\\n\\n## \u7f13\u5b58\uff1a\u5148\u641e\u6e05\u695a\u5b83\u6d3b\u5728\u54ea\u4e00\u4fa7\\n\\n\u8fd9\u662f\u6700\u5bb9\u6613\u88ab\u6df7\u7684\u4e00\u70b9\u3002react-query \u7684\u7f13\u5b58\u662f\u300c\u6bcf\u6d4f\u89c8\u5668\u300d\u7684\uff0c\u5b83\u4e0d\u8ba9\u540c\u4e00\u4e2a\u7528\u6237\u5728\u540c\u4e00\u6807\u7b7e\u9875\u91cc\u91cd\u590d\u62c9\u540c\u4e00\u4e2a\u8d44\u6e90\uff0c\u4f46\u5bf9\u4f60 BFF \u731b\u9524\u4e00\u4e2a\u6162\u4e0b\u6e38\u6beb\u65e0\u4f5c\u7528\uff0c\u56e0\u4e3a\u90a3\u6b21\u8c03\u7528\u4e0d\u5728\u6d4f\u89c8\u5668\u91cc\u3002\\n\\nalova \u7684\u7f13\u5b58\u4e5f\u662f\u5ba2\u6237\u7aef\u7b56\u7565\u7279\u6027\uff1a`cacheFor` \u63a7\u5236\u54cd\u5e94\u4fdd\u7559\u591a\u4e45\uff0c\u6a21\u5f0f\u53ea\u6709 `memory` \u548c `restore`\uff0c\u975e GET \u8bf7\u6c42\u9ed8\u8ba4\u662f `null`\uff08\u4e0d\u7f13\u5b58\uff09\u3002\u5728\u670d\u52a1\u7aef\uff0c`alova/server` \u7ed9\u4f60\u7684\u662f `retry` \u548c `createRateLimiter`\uff0c\u5b83\u5e76\u4e0d\u987a\u624b\u585e\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6e38\u54cd\u5e94\u7684\u670d\u52a1\u7aef\u7f13\u5b58\u3002\u5982\u679c\u4f60\u4e0d\u60f3\u5bf9\u91cd\u590d\u7684\u6162 GET \u53cd\u590d\u6253\u4e0b\u6e38\uff0c\u5f97\u81ea\u5df1\u52a0\u4e00\u5c42\u7f13\u5b58\uff08\u6216\u501a\u4ed7\u4e0b\u6e38\u81ea\u5df1\u5e26\u7684\uff09\uff0c\u518d\u628a `retry`/`rateLimit` \u53e0\u4e0a\u53bb\u3002\\n\\n\u6240\u4ee5\u5206\u5de5\u5f88\u5e72\u51c0\uff1areact-query \u5b88\u6d4f\u89c8\u5668\u7f13\u5b58\uff0calova/server \u5b88 BFF \u51fa\u7ad9\u7684\u91cd\u8bd5\u548c\u9650\u6d41\uff0c\u4e92\u4e0d\u76f8\u8e29\u3002\\n\\n\u4e24\u4e2a\u5de5\u5177\u7ba1\u7684\u662f\u4e0d\u540c\u5c42\u3002\u8bf7\u6c42\u6b62\u6b65\u4e8e\u6d4f\u89c8\u5668\u7684\u5730\u65b9\u7528 react-query\uff0c[BFF \u90a3\u5c42\u4ea4\u7ed9 alova/server](/blog/bff-retry)\u3002\u8981\u5b8c\u6574\u9009\u578b\u89c6\u89d2\uff0c\u89c1 [react-query \u4e0e alova \u5bf9\u6bd4](/blog/compare/react-query)\u3002\\n\\n- [\u670d\u52a1\u7aef\u91cd\u8bd5\u7b56\u7565](https://alova.js.org/tutorial/server/strategy/retry)\\n- [\u670d\u52a1\u7aef\u9650\u6d41](https://alova.js.org/tutorial/server/strategy/rate-limit)"},{"id":"/bff-retry","metadata":{"permalink":"/zh-CN/blog/bff-retry","source":"@site/i18n/zh-CN/docusaurus-plugin-content-blog/2026-08-03-bff-retry.md","title":"\u4f60\u7684 BFF \u88ab\u9650\u6d41\u6253\u6302\uff0c\u52a0\u4e00\u5c42\u91cd\u8bd5\u5c31\u597d","description":"\u4f60\u7684 Node BFF \u628a\u4e0b\u6e38\u6253\u6302\u540e\uff0c\u91cd\u8bd5\u98ce\u66b4\u53cd\u800c\u8ba9\u6545\u969c\u66f4\u7cdf\u3002\u8fd9\u7bc7\u8bb2\u600e\u4e48\u7528 alova/server \u7684 retry \u548c createRateLimiter \u52a0\u4e00\u5c42\u9000\u907f\u548c\u5ba2\u6237\u7aef\u9650\u6d41\uff0c\u4e00\u4e2a\u4e2d\u95f4\u4ef6\u5c31\u591f\u4e86\u3002","date":"2026-08-03T00:00:00.000Z","tags":[{"inline":true,"label":"bff","permalink":"/zh-CN/blog/tags/bff"},{"inline":true,"label":"node","permalink":"/zh-CN/blog/tags/node"},{"inline":true,"label":"\u91cd\u8bd5","permalink":"/zh-CN/blog/tags/\u91cd\u8bd5"},{"inline":true,"label":"\u9650\u6d41","permalink":"/zh-CN/blog/tags/\u9650\u6d41"},{"inline":true,"label":"alova-server","permalink":"/zh-CN/blog/tags/alova-server"}],"readingTime":4.63,"hasTruncateMarker":false,"authors":[{"name":"Alova Team","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"/bff-retry","title":"\u4f60\u7684 BFF \u88ab\u9650\u6d41\u6253\u6302\uff0c\u52a0\u4e00\u5c42\u91cd\u8bd5\u5c31\u597d","authors":[{"name":"Alova Team"}],"tags":["bff","node","\u91cd\u8bd5","\u9650\u6d41","alova-server"],"date":"2026-08-03T00:00:00.000Z","description":"\u4f60\u7684 Node BFF \u628a\u4e0b\u6e38\u6253\u6302\u540e\uff0c\u91cd\u8bd5\u98ce\u66b4\u53cd\u800c\u8ba9\u6545\u969c\u66f4\u7cdf\u3002\u8fd9\u7bc7\u8bb2\u600e\u4e48\u7528 alova/server \u7684 retry \u548c createRateLimiter \u52a0\u4e00\u5c42\u9000\u907f\u548c\u5ba2\u6237\u7aef\u9650\u6d41\uff0c\u4e00\u4e2a\u4e2d\u95f4\u4ef6\u5c31\u591f\u4e86\u3002","keywords":["node server request retry bff","bff rate limiter node","alova server \u91cd\u8bd5","node bff \u9650\u6d41","alova server \u9650\u6d41"]},"unlisted":false,"prevItem":{"title":"react-query \u7ba1\u4e0d\u5230 BFF\uff1falova/server \u8865\u4e0a\u91cd\u8bd5\u9650\u6d41","permalink":"/zh-CN/blog/react-query-bff-gap"},"nextItem":{"title":"react-query \u8fd8\u662f alova\uff1a\u770b\u8bf7\u6c42\u8dd1\u4e0d\u8dd1\u51fa\u6d4f\u89c8\u5668","permalink":"/zh-CN/blog/compare/react-query"}},"content":"\u4f60\u8dd1\u7740\u4e00\u4e2a Node BFF\uff0c\u5939\u5728\u524d\u7aef\u548c\u4e09\u4e2a\u4e0b\u6e38\u670d\u52a1\u4e2d\u95f4\u3002\u67d0\u5929\u4e0b\u5348\u6700\u5927\u7684\u90a3\u4e2a\u4e0b\u6e38\u5f00\u59cb\u56de 429\uff0c\u4f60\u7684 BFF \u5bf9\u6bcf\u4e2a 429 \u7684\u56de\u5e94\u662f\uff1a\u7acb\u523b\u628a\u540c\u4e00\u4e2a\u8bf7\u6c42\u518d\u53d1\u4e00\u904d\u3002\u4e00\u5206\u949f\u4e4b\u5185\uff0c\u4e0b\u6e38\u88ab\u300c\u5b83\u5df2\u7ecf\u62d2\u7edd\u8fc7\u7684\u8bf7\u6c42\u7684\u91cd\u8bd5\u300d\u57cb\u4e86\uff0c\u4f60\u7684\u524d\u7aef\u770b\u5230\u4e00\u6574\u9762 500\u3002\u8fd9\u573a\u666f\u719f\u4e0d\u719f\u6089\uff1f\\n\\n\u4e0b\u9762\u8fd9\u79cd\u5199\u6cd5\u6700\u5bb9\u6613\u628a\u4f60\u5e26\u5230\u6c9f\u91cc\uff1a\\n\\n```js\\napp.get(\'/api/resource/:id\', async (req, res) => {\\n  try {\\n    const data = await fetch(`https://downstream.internal/resource/${req.params.id}`);\\n    res.json(await data.json());\\n  } catch (err) {\\n    // \u6734\u7d20\u91cd\u8bd5\uff1a\u73b0\u5728\u5c31\u518d\u53d1\u4e00\u6b21\\n    const retry = await fetch(`https://downstream.internal/resource/${req.params.id}`);\\n    res.json(await retry.json());\\n  }\\n});\\n```\\n\\n\u5b83\u770b\u8d77\u6765\u4eba\u755c\u65e0\u5bb3\uff0c\u76f4\u5230\u51fa\u4e8b\u3002\u91cc\u9762\u85cf\u7740\u4e24\u4e2a\u95ee\u9898\uff1a\\n\\n1. **\u91cd\u8bd5\u4e0d\u770b\u4e3a\u4ec0\u4e48\u5931\u8d25\u3002** 429 \u7684\u610f\u601d\u662f\u300c\u6162\u70b9\u300d\u3002\u7acb\u523b\u91cd\u8bd5\u662f\u6162\u70b9\u7684\u53cd\u4e49\u8bcd\uff0c\u4f60\u628a\u4f60\u521a\u641e\u7838\u7684\u90a3\u4e2a\u72b6\u6001\u53c8\u653e\u5927\u4e86\u4e00\u904d\u3002\\n2. **\u6ca1\u6709\u5ba2\u6237\u7aef\u9650\u6d41\u3002** BFF \u4e0d\u7ba1\u4e0d\u987e\u5730\u628a\u6bcf\u4e2a\u8fdb\u6765\u7684\u8bf7\u6c42\u90fd\u8f6c\u53d1\u7ed9\u5df2\u7ecf\u5598\u4e0d\u4e0a\u6c14\u7684\u4e0b\u6e38\uff0c\u6ca1\u6709\u4efb\u4f55\u4e1c\u897f\u7ed9\u4e0b\u6e38\u515c\u5e95\u3002\\n\\n\u5982\u679c\u4f60\u8dd1\u4e86\u4e0d\u6b62\u4e00\u4e2a BFF \u5b9e\u4f8b\uff0c\u624b\u5199\u8ba1\u6570\u5668\uff08\u6a21\u5757\u7ea7\u53d8\u91cf\u3001\u5185\u5b58 Map\uff09\u4e5f\u6551\u4e0d\u4e86\u4f60\u3002\u6bcf\u4e2a\u8fdb\u7a0b\u5404\u7b97\u5404\u7684\uff0c\u4e8e\u662f\u4f60\u4ee5\u4e3a\u7684\u300c\u6bcf\u79d2 4 \u6b21\u300d\u4e0a\u9650\uff0c\u5b9e\u9645\u53d8\u6210\u4e86\u6bcf\u4e2a\u5b9e\u4f8b\u6bcf\u79d2 4 \u6b21\u3002\u4e09\u4e2a\u8282\u70b9\u52a0\u8d77\u6765\u5c31\u662f\u6bcf\u79d2 12 \u6b21\u3002\\n\\n## \u8fd9\u4e00\u5c42\u5230\u5e95\u9700\u8981\u4ec0\u4e48\\n\\n\u5148\u522b\u7ba1\u5e93\u3002\u4e00\u4e2a\u625b\u5f97\u4f4f\u9650\u6d41\u7684\u4e0b\u6e38\u8c03\u7528\u5c42\uff0c\u81f3\u5c11\u5f97\u6709\u8fd9\u4e9b\u80fd\u529b\uff1a\\n\\n- **\u9000\u907f\uff0c\u800c\u4e0d\u662f\u7acb\u523b\u91cd\u53d1\u3002** \u7b49\u4e00\u4f1a\u513f\uff0c\u518d\u7b49\u6bd4\u521a\u624d\u66f4\u4e45\u3002\u6307\u6570\u9000\u907f\u52a0\u4e00\u70b9\u6296\u52a8\uff0c\u80fd\u8ba9\u6240\u6709\u5b9e\u4f8b\u522b\u8e29\u7740\u540c\u4e00\u4e2a\u62cd\u5b50\u91cd\u8bd5\u3002\\n- **\u91cd\u8bd5\u8981\u5c01\u9876\u3001\u8981\u6311\u5931\u8d25\u3002** \u8bd5\u51e0\u6b21\u5c31\u505c\uff0c\u800c\u4e14\u53ea\u9488\u5bf9\u503c\u5f97\u91cd\u8bd5\u7684\u5931\u8d25\uff08\u8d85\u65f6\u30015xx\u3001429\uff09\uff0c\u5bf9\u6c38\u8fdc\u4e0d\u6210\u7684 4xx \u522b\u6d6a\u8d39\u6b21\u6570\u3002\\n- **\u5ba2\u6237\u7aef\u9650\u6d41\u3002** \u5728\u771f\u6b63\u8c03\u7528\u4e0b\u6e38\u4e4b\u524d\u5148\u67e5\u4e00\u4efd\u5927\u5bb6\u5171\u4eab\u7684\u989d\u5ea6\uff0c\u522b\u5f80\u706b\u91cc\u6dfb\u67f4\u3002\\n- **\u8ba1\u6570\u5668\u8981\u8de8\u8fdb\u7a0b\u3002** \u8fd9\u4e2a\u989d\u5ea6\u5f97\u653e\u5728\u6240\u6709\u5b9e\u4f8b\u90fd\u8ba4\u7684\u5730\u65b9\uff0c\u4e0d\u662f\u67d0\u4e2a\u8fdb\u7a0b\u7684\u5185\u5b58\u91cc\u3002\\n\\n\u5168\u624b\u5199\u7684\u8bdd\uff0c\u4e0a\u9762\u7684 plumbing \u4e0d\u5c0f\u3002alova \u7684 server \u7aef\u7ed9\u4e86\u4e24\u4e2a hook\uff0c\u524d\u4e09\u9879\u76f4\u63a5\u8986\u76d6\uff0c\u7b2c\u56db\u9879\u9760\u4e00\u4e2a\u53ef\u63d2\u62d4\u7684\u5b58\u50a8\u3002\\n\\n## retry + createRateLimiter\uff0c\u4e00\u4e2a\u4e2d\u95f4\u4ef6\\n\\nalova \u662f\u4e00\u5957\u8bf7\u6c42\u7b56\u7565\u5c42\u3002\u5728\u670d\u52a1\u7aef\uff0c`alova/server` \u63d0\u4f9b\u4e86\u5305\u88f9\u8bf7\u6c42 method \u7684 hook\uff1a`retry` \u52a0\u9000\u907f\uff0c`createRateLimiter` \u52a0\u5ba2\u6237\u7aef\u9650\u6d41\u3002\u5b83\u4eec\u5305\u7684\u90fd\u662f\u4f60\u672c\u6765\u5c31\u62ff\u53bb\u8c03\u4e0b\u6e38\u7684\u90a3\u4e2a method \u5b9e\u4f8b\u3002\\n\\n\u5148\u5efa\u4e00\u4e2a alova \u5b9e\u4f8b\u3002\u670d\u52a1\u7aef\u6211\u7528 axios \u9002\u914d\u5668\uff0c\u8bf7\u6c42\u8fd8\u662f\u4ece axios \u51fa\u53bb\uff0calova \u53ea\u8d1f\u8d23\u300c\u600e\u4e48\u8bf7\u6c42\u300d\u8fd9\u4e00\u5c42\uff1a\\n\\n```js\\nconst { createAlova } = require(\'alova\');\\nconst { axiosRequestAdapter } = require(\'@alova/adapter-axios\');\\nconst { retry, createRateLimiter } = require(\'alova/server\');\\n\\nconst alovaInst = createAlova({\\n  baseURL: \'https://downstream.internal\',\\n  requestAdapter: axiosRequestAdapter()\\n});\\n\\n// \u6bcf 4 \u79d2\u7a97\u53e3 4 \u4e2a\u70b9\uff0c\u989d\u5ea6\u8bb0\u5728 method \u7684\u7f13\u5b58\u5b58\u50a8\u91cc\\nconst rateLimit = createRateLimiter({ duration: 4000, points: 4 });\\n```\\n\\n\u7136\u540e\u5305\u4f4f\u4e0b\u6e38\u8c03\u7528\u3002`retry` \u653e\u91cc\u9762\uff0c`rateLimit` \u653e\u5916\u9762\uff1a\\n\\n```js\\napp.get(\'/api/resource/:id\', async (req, res) => {\\n  try {\\n    const data = await rateLimit(\\n      retry(alovaInst.Get(`/resource/${req.params.id}`), {\\n        retry: 5,\\n        backoff: { delay: 1000, multiplier: 2 }\\n      }),\\n      { key: `downstream:${req.params.id}` }\\n    );\\n    res.json(data);\\n  } catch (err) {\\n    // \u89e6\u53d1\u9650\u6d41\uff0c\u6216\u91cd\u8bd5\u8017\u5c3d\\n    res.status(429).json({ error: \'downstream busy, retry later\' });\\n  }\\n});\\n```\\n\\n\u548c\u6734\u7d20\u7248\u6bd4\uff0c\u6539\u52a8\u5728\u8fd9\u51e0\u5904\uff1a\\n\\n- `retry: 5` \u5c01\u4e86\u6b21\u6570\u3002`backoff.delay: 1000` \u914d `multiplier: 2`\uff0c\u95f4\u9694\u62c9\u6210 1s\u30012s\u30014s\u30018s\uff0c\u88ab\u4e0b\u6e38\u6253\u8db4\u7684\u65f6\u5019\u5b83\u5598\u53e3\u6c14\uff0c\u800c\u4e0d\u662f\u7acb\u523b\u8865\u7b2c\u4e8c\u5200\u3002\\n- `rateLimit` \u5728\u8bf7\u6c42\u771f\u6b63\u5230\u8fbe\u4e0b\u6e38\u4e4b\u524d\u5148\u6263\u4e00\u4e2a\u70b9\u3002\u4e00\u4e2a\u7a97\u53e3\u91cc\u53ea\u6709 4 \u4e2a\u80fd\u8fc7\u53bb\uff0c\u5176\u4f59\u7684\u4f1a\u629b\u9519\u3001\u4f60\u65e9\u65e9\u56de 429\uff0c\u4e0b\u6e38\u4e0d\u88ab\u4f60\u81ea\u5df1\u7684\u6d41\u91cf\u538b\u57ae\u3002\\n- `key` \u628a\u989d\u5ea6\u6309\u4e0b\u6e38\u8d44\u6e90\u5206\u5f00\uff0c\u4e00\u4e2a\u70ed\u70b9 key \u4e0d\u4f1a\u628a\u522b\u7684\u8d44\u6e90\u997f\u6b7b\u3002\\n\\nretry \u7684\u9ed8\u8ba4\u503c\u5728\u8fd9\u91cc\u4e5f\u6709\u610f\u4e49\uff1a\u4e0d\u4f20\u53c2\u6570\u65f6\u5b83\u91cd\u8bd5 3 \u6b21\u3001\u6bcf\u6b21\u9694 1 \u79d2\u3002\u6211\u4eec\u6539\u5927\uff0c\u662f\u56e0\u4e3a\u8fd9\u4e2a\u4e0b\u6e38\u591f\u4e0d\u7a33\u5b9a\u3001\u503c\u5f97\u591a\u8bd5\u51e0\u6b21\u3002\\n\\n### \u96c6\u7fa4\u90a3\u4e00\u5757\\n\\n\u9ed8\u8ba4\u7684\u9650\u6d41\u5b58\u50a8\u662f method \u7684 `l2Cache`\u3002\u5355\u8fdb\u7a0b\u4e0b\u5c31\u662f\u5185\u5b58\uff0c\u591f\u7528\u3002\u8de8\u5b9e\u4f8b\u65f6\u4f60\u628a `store` \u6307\u5230\u4e00\u4efd\u5171\u4eab\u5b58\u50a8\uff0c\u6bd4\u5982 `@alova/psc` \u6216 redis \u9002\u914d\u5668\uff0c\u6240\u6709\u8282\u70b9\u4ece\u540c\u4e00\u4e2a\u989d\u5ea6\u91cc\u6263\u3002\u8fd9\u4e00\u5757\u662f\u624b\u5199\u5185\u5b58\u8ba1\u6570\u5668\u81ea\u5df1\u6c38\u8fdc\u9020\u4e0d\u51fa\u6765\u7684\uff0c\u9664\u975e\u4f60\u4e13\u95e8\u53bb\u642d\u3002\\n\\n## \u4f60\u80fd\u62ff\u5230\u4ec0\u4e48\\n\\n\u4e0d\u662f\u57fa\u51c6\u6d4b\u8bd5\uff0c\u53ea\u662f\u8fd9\u4efd\u914d\u7f6e\u5b9e\u9645\u4ea7\u751f\u7684\u884c\u4e3a\uff1a\\n\\n| \u573a\u666f | \u6734\u7d20 handler | \u52a0 retry + rateLimit |\\n| --- | --- | --- |\\n| \u4e0b\u6e38\u56de 429 | \u7acb\u523b\u91cd\u8bd5\uff0c\u66f4\u91cd\u7684\u8d1f\u8f7d | \u9000\u907f\u7b49\u5f85\uff0c5 \u6b21\u540e\u505c |\\n| \u4e09\u4e2a BFF \u8282\u70b9\uff0c\u4e0a\u9650 4/s | \u5b9e\u9645\u53d1\u4e86 12/s | \u8de8\u8282\u70b9\u5171 4/s\uff08\u5171\u4eab\u5b58\u50a8\u4e0b\uff09 |\\n| \u540c\u4e00\u8bf7\u6c42\u6765\u4e86\u4e24\u6b21 | \u4e24\u4e2a\u90fd\u5728\u98de | \u7b2c\u4e8c\u6b21\u590d\u7528\u7b2c\u4e00\u6b21\u5728\u9014\u7684\u8bf7\u6c42 |\\n\\n\u6700\u540e\u4e00\u884c\u662f\u8bf7\u6c42\u5171\u4eab\uff1aalova \u4f1a\u628a\u5b8c\u5168\u76f8\u540c\u7684\u5e76\u53d1\u8bf7\u6c42\u53bb\u91cd\uff0c\u4e24\u4e2a\u7528\u6237\u8981\u540c\u4e00\u4e2a\u8d44\u6e90\uff0c\u4e0d\u4f1a\u89e6\u53d1\u4e24\u6b21\u4e0b\u6e38\u8c03\u7528\u3002\\n\\n\u5982\u679c\u4f60\u7684 BFF \u8c03\u7684\u4e0b\u6e38\u4f1a\u9650\u6d41\uff0c\u800c\u4e14\u4f60\u8dd1\u4e86\u4e0d\u6b62\u4e00\u4e2a\u5b9e\u4f8b\uff0c\u4e0a\u9762\u8fd9\u5957\u7ec4\u5408\u503c\u5f97\u82b1\u4e00\u4e2a\u4e0b\u5348\u3002\\n\\n- [\u670d\u52a1\u7aef\u91cd\u8bd5\u7b56\u7565](https://alova.js.org/tutorial/server/strategy/retry)\\n- [\u670d\u52a1\u7aef\u9650\u6d41](https://alova.js.org/tutorial/server/strategy/rate-limit)"},{"id":"/compare/react-query","metadata":{"permalink":"/zh-CN/blog/compare/react-query","source":"@site/i18n/zh-CN/docusaurus-plugin-content-blog/2026-08-03-react-query-vs-alova.md","title":"react-query \u8fd8\u662f alova\uff1a\u770b\u8bf7\u6c42\u8dd1\u4e0d\u8dd1\u51fa\u6d4f\u89c8\u5668","description":"\u4e00\u7bc7\u8bda\u5b9e\u7684 react-query \u4e0e alova \u5bf9\u6bd4\uff0c\u5305\u62ec alova \u66f4\u5f31\u7684\u5730\u65b9\u3002react-query \u5b88\u7740 React \u6d4f\u89c8\u5668\u4fa7\u7f13\u5b58\uff1balova \u628a\u540c\u4e00\u5957\u8bf7\u6c42\u903b\u8f91\u8dd1\u5728\u79fb\u52a8\u7aef\u548c Node BFF \u4e0a\u3002","date":"2026-08-03T00:00:00.000Z","tags":[{"inline":true,"label":"react-query","permalink":"/zh-CN/blog/tags/react-query"},{"inline":true,"label":"\u5bf9\u6bd4","permalink":"/zh-CN/blog/tags/\u5bf9\u6bd4"},{"inline":true,"label":"alova","permalink":"/zh-CN/blog/tags/alova"}],"readingTime":3.22,"hasTruncateMarker":false,"authors":[{"name":"Alova Team","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"/compare/react-query","title":"react-query \u8fd8\u662f alova\uff1a\u770b\u8bf7\u6c42\u8dd1\u4e0d\u8dd1\u51fa\u6d4f\u89c8\u5668","authors":[{"name":"Alova Team"}],"tags":["react-query","\u5bf9\u6bd4","alova"],"date":"2026-08-03T00:00:00.000Z","description":"\u4e00\u7bc7\u8bda\u5b9e\u7684 react-query \u4e0e alova \u5bf9\u6bd4\uff0c\u5305\u62ec alova \u66f4\u5f31\u7684\u5730\u65b9\u3002react-query \u5b88\u7740 React \u6d4f\u89c8\u5668\u4fa7\u7f13\u5b58\uff1balova \u628a\u540c\u4e00\u5957\u8bf7\u6c42\u903b\u8f91\u8dd1\u5728\u79fb\u52a8\u7aef\u548c Node BFF \u4e0a\u3002","keywords":["react-query \u5bf9\u6bd4 alova","alova react-query \u5bf9\u6bd4","alova \u670d\u52a1\u7aef","react-query \u5c40\u9650"]},"unlisted":false,"prevItem":{"title":"\u4f60\u7684 BFF \u88ab\u9650\u6d41\u6253\u6302\uff0c\u52a0\u4e00\u5c42\u91cd\u8bd5\u5c31\u597d","permalink":"/zh-CN/blog/bff-retry"},"nextItem":{"title":"axios \u548c alova \u4e00\u8d77\u7528\uff0c\u8c01\u7ba1\u4ec0\u4e48","permalink":"/zh-CN/blog/compare/axios"}},"content":"\u9009\u6570\u636e\u8bf7\u6c42\u5e93\uff0c\u901a\u5e38\u5f00\u5934\u90fd\u662f\u300c\u8c01\u7684\u7f13\u5b58\u66f4\u597d\u300d\u3002\u8fd9\u4e2a\u95ee\u9898\u8df3\u8fc7\u4e86\u4e00\u4e2a\u4e8b\u540e\u624d\u54ac\u4eba\u7684\u70b9\uff1a\u4f60\u7684\u8bf7\u6c42\u5230\u5e95\u8dd1\u5728\u54ea\uff1f\\n\\n\u5982\u679c\u4f60\u7684\u8bf7\u6c42\u5168\u5728\u6d4f\u89c8\u5668\u91cc\u3001\u800c\u4e14\u7528 React\uff0creact-query \u662f\u6210\u719f\u3001\u8e29\u5751\u5c11\u7684\u9009\u62e9\u3002\u53ef\u4e00\u65e6\u4f60\u9700\u8981\u540c\u4e00\u5957\u8bf7\u6c42\u903b\u8f91\u8dd1\u5728\u300c\u4e0d\u662f React Native \u7684\u624b\u673a\u7aef\u300d\uff0c\u6216\u8005\u8dd1\u5728\u4e00\u4e2a\u8c03\u4e0b\u6e38\u670d\u52a1\u7684 BFF \u91cc\uff0c\u5730\u56fe\u5c31\u53d8\u4e86\u3002alova \u628a\u8fd9\u4e9b\u60c5\u51b5\u6536\u5230\u4e86\u540c\u4e00\u5957 API \u4e0b\u3002\u8fd9\u7bc7\u662f\u76f4\u6765\u76f4\u53bb\u7684\u5bf9\u6bd4\uff0c\u4e5f\u5305\u62ec alova \u66f4\u5f31\u7684\u5730\u65b9\u3002\\n\\n## react-query \u660e\u663e\u9886\u5148\u7684\u5730\u65b9\\n\\n\u5148\u8bb2\u8bda\u5b9e\u7684\u4e00\u9762\uff1a\\n\\n- **\u548c React \u8d34\u5408\u3002** react-query \u662f\u56f4\u7740 React \u7684\u6e32\u67d3\u6a21\u578b\u5efa\u7684\u3002`useQuery` \u8fd9\u7c7b hook \u5929\u7136\u5d4c\u8fdb\u7ec4\u4ef6\uff0c\u5b83\u7684 devtools \u548c\u67e5\u8be2\u9762\u677f\u662f\u8fd9\u4e2a\u9886\u57df\u91cc\u6700\u987a\u624b\u7684\u3002\\n- **\u7f13\u5b58\u6210\u719f\u5ea6\u3002** \u5b83\u7684\u7f13\u5b58\u3001\u53bb\u91cd\u3001\u540e\u53f0\u91cd\u62c9\u3001stale-while-revalidate\uff0c\u5728\u5927\u91cf\u751f\u4ea7\u5e94\u7528\u91cc\u88ab\u53cd\u590d\u9a8c\u8bc1\u8fc7\u3002\\n- **\u793e\u533a\u4e0e\u7b54\u6848\u3002** \u8fd9\u4e48\u591a\u5e74\u7684 Stack Overflow\u3001\u535a\u5ba2\u3001\u80fd\u76f4\u63a5\u6284\u7684\u7247\u6bb5\uff0c\u610f\u5473\u7740\u5927\u90e8\u5206\u95ee\u9898\u7f51\u4e0a\u5df2\u7ecf\u6709\u4eba\u89e3\u8fc7\u4e86\u3002\\n\\n\u5982\u679c\u4f60\u7684\u524d\u7aef\u662f React\u3001\u53ea\u5728\u6d4f\u89c8\u5668\u91cc\u3001\u4f60\u4e5f\u5bf9\u8fd9\u4e2a\u751f\u6001\u6ee1\u610f\uff0creact-query \u662f\u66f4\u7a33\u7684\u9ed8\u8ba4\u3002\u8bf4\u53cd\u8bdd\u662f\u4e0d\u8bda\u5b9e\u7684\u3002\\n\\n## alova \u8d70\u5f97\u66f4\u8fdc\u7684\u5730\u65b9\\n\\nalova \u4e5f\u662f\u8bf7\u6c42\u7b56\u7565\u5c42\uff0c\u4f46\u5b83\u4e0d\u7ed1\u6b7b\u67d0\u4e2a\u6846\u67b6\u6216\u67d0\u4e2a\u8fd0\u884c\u65f6\uff1a\\n\\n- **\u4e00\u5957 API \u8de8\u8fd0\u884c\u65f6\u3002** \u540c\u4e00\u5957 `useRequest`\u3001`usePagination` \u8c03\u7528\uff0c\u8dd1\u5728 Web\u3001\u79fb\u52a8\u7aef\uff08React Native / Expo / uni-app / Taro / \u5c0f\u7a0b\u5e8f\uff09\u3001\u4ee5\u53ca\u670d\u52a1\u7aef\uff08Node BFF\uff09\u3002\u8bf7\u6c42\u903b\u8f91\u4f60\u53ea\u5199\u4e00\u904d\u3002\\n- **\u670d\u52a1\u7aef hook\u3002** `alova/server` \u7ed9 BFF \u7684\u51fa\u7ad9\u8c03\u7528\u52a0\u4e86 `retry` \u548c `createRateLimiter`\uff0c\u8fd9\u4e00\u5c42 react-query \u7ba1\u4e0d\u5230\uff0c\u56e0\u4e3a\u5b83\u6d3b\u5728\u6d4f\u89c8\u5668\u91cc\u3002\\n- **\u6846\u67b6\u4efb\u9009\u3002** React\u3001Vue\u3001Svelte\u3001Solid \u90fd\u6709\u4e00\u7b49\u516c\u6c11\u7ea7\u522b\u7684 hook\uff0c\u6df7\u5408\u6280\u672f\u6808\u7684\u56e2\u961f\u4e0d\u5fc5\u88ab\u7ed1\u8fdb React\u3002\\n- **\u7ad9\u5728\u4f60\u73b0\u6709\u7684\u9002\u914d\u5668\u4e0a\u3002** alova \u81ea\u5df1\u4e0d\u53d1\u8bf7\u6c42\uff0c\u5b83\u8dd1\u5728 fetch \u6216 axios \u9002\u914d\u5668\u4e4b\u4e0a\uff0c\u6240\u4ee5\u4f60\u5df2\u7ecf\u5728\u7528 axios \u7684\u8bdd\uff0c\u5b83\u7ee7\u7eed\u5e72\u6d3b\u3002\\n\\n## \u9010\u9879\u5bf9\u7167\\n\\n| \u5173\u6ce8\u70b9 | react-query | alova |\\n| --- | --- | --- |\\n| \u4e3b\u8fd0\u884c\u65f6 | \u6d4f\u89c8\u5668\uff08React\uff09 | Web\u3001\u79fb\u52a8\u7aef\u3001\u670d\u52a1\u7aef\uff08BFF\uff09 |\\n| \u6846\u67b6 | React \u4f18\u5148 | React / Vue / Svelte / Solid |\\n| \u5ba2\u6237\u7aef\u7f13\u5b58 | \u6781\u4f73\u3001\u6210\u719f | \u4e0d\u9519\uff0c\u7b56\u7565 hook |\\n| \u670d\u52a1\u7aef\u91cd\u8bd5 / \u9650\u6d41 | \u4e0d\u5f52\u5b83\u7ba1 | `alova/server` hook |\\n| \u8de8\u7aef App | \u4ec5 React Native | React Native\u3001Expo\u3001uni-app\u3001Taro\u3001\u5c0f\u7a0b\u5e8f |\\n| \u81ea\u5df1\u53d1 HTTP | \u5426\uff08\u5e95\u5c42 fetch/axios\uff09 | \u5426\uff08fetch/axios \u9002\u914d\u5668\uff09 |\\n| \u793e\u533a\u89c4\u6a21 | \u975e\u5e38\u5927 | \u8f83\u5c0f |\\n\\n\u6700\u540e\u4e00\u884c\u8bf4\u660e\uff1a\u4e24\u4e2a\u5e93\u90fd\u4e0d\u66ff\u4ee3 axios\u3002\u5b83\u4eec\u90fd\u5750\u5728\u8bf7\u6c42\u9002\u914d\u5668\u4e4b\u4e0a\uff0c\u6240\u4ee5\u56e2\u961f\u5df2\u7ecf\u5728\u7528 axios \u7684\u8bdd\uff0c\u53d1\u8bf7\u6c42\u8fd8\u662f\u5b83\u7684\u6d3b\u3002\\n\\n## \u4ec0\u4e48\u65f6\u5019 react-query \u66f4\u5bf9\\n\\n- \u524d\u7aef\u662f React\u3001\u53ea\u5728\u6d4f\u89c8\u5668\uff0c\u4f60\u60f3\u8981\u6700\u6df1\u7684 React \u7f13\u5b58\u751f\u6001\u3002\\n- \u4f60\u4e0d\u8dd1\u4e00\u4e2a\u9700\u8981\u51fa\u7ad9\u91cd\u8bd5/\u9650\u6d41\u7684 BFF\u3002\\n- \u56e2\u961f\u5df2\u7ecf\u719f react-query\uff0c\u7528\u5b83\u51fa\u6d3b\u5feb\u3002\\n\\n## \u4ec0\u4e48\u65f6\u5019 alova \u66f4\u5408\u9002\\n\\n- \u4f60\u8981\u8de8 Web\u3001\u975e React Native \u7684 App\u3001Node BFF \u7ef4\u62a4\u540c\u4e00\u5957\u8bf7\u6c42\u903b\u8f91\u3002\\n- \u4f60\u7684 BFF \u9700\u8981\u5bf9\u4e0b\u6e38\u8c03\u7528\u505a\u9000\u907f\u91cd\u8bd5\u52a0\u5ba2\u6237\u7aef\u9650\u6d41\uff08\u89c1 [BFF \u91cd\u8bd5\u90a3\u7bc7](/blog/bff-retry)\uff09\u3002\\n- \u4f60\u5728\u7528 Vue/Svelte/Solid\uff0c\u6216\u6df7\u5408\u6808\uff0c\u60f3\u8981\u4e00\u4e2a\u7b56\u7565\u5c42\u3002\\n\\n## \u4ec0\u4e48\u60c5\u51b5\u4e0b\u4e24\u4e2a\u90fd\u4e0d\u9700\u8981\\n\\n\u5982\u679c\u4f60\u5c31\u53d1\u51e0\u4e2a\u8bf7\u6c42\uff0c\u624b\u5199 `loading`/`data`/`error` \u4e09\u4e2a\u72b6\u6001\u4e5f\u4e0d\u91cd\u590d\uff0c\u90a3 `fetch` \u52a0\u4e00\u4e2a\u5c0f\u5c01\u88c5\u5c31\u591f\u4e86\u3002\u4e24\u4e2a\u5e93\u53ea\u6709\u5728\u300c\u540c\u4e00\u7c7b\u8bf7\u6c42\u6a21\u5f0f\u53cd\u590d\u51fa\u73b0\u300d\u65f6\u624d\u503c\u56de\u7968\u4ef7\u3002\\n\\n- [alova \u4e0e\u5176\u4ed6\u5e93\u5bf9\u6bd4](https://alova.js.org/about/comparison)\\n- [\u670d\u52a1\u7aef\u91cd\u8bd5\u7b56\u7565](https://alova.js.org/tutorial/server/strategy/retry)"},{"id":"/compare/axios","metadata":{"permalink":"/zh-CN/blog/compare/axios","source":"@site/i18n/zh-CN/docusaurus-plugin-content-blog/2026-07-30-axios-and-alova.md","title":"axios \u548c alova \u4e00\u8d77\u7528\uff0c\u8c01\u7ba1\u4ec0\u4e48","description":"axios \u548c alova \u4e0d\u662f\u7ade\u4e89\u5173\u7cfb\u3002axios \u8d1f\u8d23\u53d1\u8bf7\u6c42\uff0calova \u8d1f\u8d23\u600e\u4e48\u8bf7\u6c42\u2014\u2014\u5206\u9875\u3001\u7f13\u5b58\u3001\u91cd\u8bd5\uff1baxios \u53ef\u4ee5\u76f4\u63a5\u4f5c\u4e3a alova \u7684\u8bf7\u6c42\u9002\u914d\u5668\u7ee7\u7eed\u5de5\u4f5c\u3002","date":"2026-07-30T00:00:00.000Z","tags":[{"inline":true,"label":"axios","permalink":"/zh-CN/blog/tags/axios"},{"inline":true,"label":"\u5bf9\u6bd4","permalink":"/zh-CN/blog/tags/\u5bf9\u6bd4"}],"readingTime":2.86,"hasTruncateMarker":false,"authors":[{"name":"Alova Team","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"/compare/axios","title":"axios \u548c alova \u4e00\u8d77\u7528\uff0c\u8c01\u7ba1\u4ec0\u4e48","authors":[{"name":"Alova Team"}],"tags":["axios","\u5bf9\u6bd4"],"date":"2026-07-30T00:00:00.000Z","description":"axios \u548c alova \u4e0d\u662f\u7ade\u4e89\u5173\u7cfb\u3002axios \u8d1f\u8d23\u53d1\u8bf7\u6c42\uff0calova \u8d1f\u8d23\u600e\u4e48\u8bf7\u6c42\u2014\u2014\u5206\u9875\u3001\u7f13\u5b58\u3001\u91cd\u8bd5\uff1baxios \u53ef\u4ee5\u76f4\u63a5\u4f5c\u4e3a alova \u7684\u8bf7\u6c42\u9002\u914d\u5668\u7ee7\u7eed\u5de5\u4f5c\u3002"},"unlisted":false,"prevItem":{"title":"react-query \u8fd8\u662f alova\uff1a\u770b\u8bf7\u6c42\u8dd1\u4e0d\u8dd1\u51fa\u6d4f\u89c8\u5668","permalink":"/zh-CN/blog/compare/react-query"},"nextItem":{"title":"uni-app \u5206\u9875\u5217\u8868\uff1a\u7528\u4e00\u4e2a hook \u89e3\u51b3\u7ade\u6001\u3001\u91cd\u590d\u8bf7\u6c42\u548c\u52a0\u8f7d\u72b6\u6001","permalink":"/zh-CN/blog/blog/uniapp-pagination"}},"content":"**\u4e00\u53e5\u8bdd\uff1a\u5b83\u4eec\u662f\u5206\u5c42\u5173\u7cfb\uff0c\u4e0d\u662f\u4e8c\u9009\u4e00\u3002** axios \u662f HTTP \u5ba2\u6237\u7aef\uff0c\u8d1f\u8d23\u628a\u8bf7\u6c42\u53d1\u51fa\u53bb\uff1balova \u662f\u8bf7\u6c42\u7b56\u7565\u5c42\uff0c\u8d1f\u8d23\u300c\u600e\u4e48\u8bf7\u6c42\u300d\u2014\u2014\u5206\u9875\u3001\u7f13\u5b58\u3001\u91cd\u8bd5\u3001\u53bb\u91cd\u3001token \u5237\u65b0\u3002alova \u53ef\u4ee5\u628a axios \u7528\u4f5c\u8bf7\u6c42\u9002\u914d\u5668\uff08`@alova/adapter-axios`\uff09\uff0c\u6240\u4ee5\u9009 alova \u4ece\u6765\u4e0d\u610f\u5473\u7740\u6254\u6389 axios\u3002\\n\\nalova \u7684\u5b9a\u4f4d\uff1a\u4e00\u5957\u8bf7\u6c42 API\uff0c\u8dd1\u5728 Web\u3001App\uff08uni-app/Taro/\u5c0f\u7a0b\u5e8f\uff09\u3001\u670d\u52a1\u7aef\uff08BFF\uff09\u3002\\n\\n## \u5206\u5de5\u8868\\n\\n| \u5173\u6ce8\u70b9 | axios | alova |\\n| --- | --- | --- |\\n| \u53d1\u9001 HTTP \u8bf7\u6c42 | \u2705 \u672c\u804c | \u4ea4\u7ed9\u9002\u914d\u5668\uff08fetch / XHR / **axios** / uni-app / Taro\uff09 |\\n| \u62e6\u622a\u5668 | \u2705 | \u2705 `beforeRequest` / `responded`\uff08\u4f60\u7684 axios \u62e6\u622a\u5668\u7ee7\u7eed\u751f\u6548\uff09 |\\n| loading / error / data \u72b6\u6001 | \u624b\u5199 | \u2705 `useRequest` \u7b49\u81ea\u52a8\u7ba1\u7406 |\\n| \u5206\u9875\u3001\u8868\u5355\u3001\u4e0a\u4f20\u3001SSE \u6d41\u7a0b | \u624b\u5199 | \u2705 20+ \u73b0\u6210\u7b56\u7565 hooks |\\n| \u54cd\u5e94\u7f13\u5b58 | \u624b\u5199 | \u2705 \u591a\u7ea7\u7f13\u5b58\uff08L1/L2\uff09\uff0b\u58f0\u660e\u5f0f\u5931\u6548 |\\n| \u76f8\u540c\u5e76\u53d1\u8bf7\u6c42\u53bb\u91cd | \u624b\u5199 | \u2705 \u5185\u7f6e\u8bf7\u6c42\u5171\u4eab |\\n| \u8de8\u7aef\uff08uni-app / Taro / \u5c0f\u7a0b\u5e8f\uff09 | \u793e\u533a\u5c01\u88c5 | \u2705 \u5b98\u65b9\u9002\u914d\u5668\uff0c\u540c\u4e00\u5957 API |\\n| \u670d\u52a1\u7aef\u91cd\u8bd5 / \u9650\u6d41 | \u624b\u5199 | \u2705 `alova/server` |\\n\\n## axios \u5b9e\u6253\u5b9e\u66f4\u5f3a\u7684\u5730\u65b9\\n\\n\u8bda\u5b9e\u7684\u5bf9\u6bd4\u8981\u5199\u4e24\u9762\uff1a\\n\\n- **\u751f\u6001\u4e0e\u719f\u6089\u5ea6\u3002** axios \u62e5\u6709 JavaScript \u4e16\u754c\u6700\u5927\u7684\u793e\u533a\u4e4b\u4e00\uff0c\u51e0\u4e4e\u6bcf\u4e2a\u8fb9\u89d2\u95ee\u9898\u90fd\u6709\u73b0\u6210\u7b54\u6848\uff0c\u51e0\u4e4e\u6bcf\u4e2a\u5f00\u53d1\u8005\u90fd\u7528\u8fc7\u5b83\uff1balova \u7684\u793e\u533a\u89c4\u6a21\u8fdc\u5c0f\u4e8e\u5b83\u3002\\n- **\u56e2\u961f\u96f6\u5b66\u4e60\u6210\u672c\u3002** \u6240\u6709\u4eba\u90fd\u4f1a `axios.get()`\uff1balova \u5f15\u5165\u4e86 `Method` \u62bd\u8c61\u548c\u7b56\u7565 hooks\uff0c\u8fd9\u662f\u771f\u5b9e\u5b58\u5728\u7684\uff08\u867d\u7136\u4e0d\u5927\u7684\uff09\u5fc3\u667a\u8d1f\u62c5\u3002\\n- **\u8bf7\u6c42\u672c\u6765\u5c31\u5c11\u7684\u9879\u76ee**\uff0caxios \u5355\u72ec\u7528\u5c31\u591f\u4e86\u3002\u7b56\u7565\u5c42\u53ea\u6709\u5728\u4f60\u53cd\u590d\u624b\u5199\u540c\u6837\u7684\u8bf7\u6c42\u903b\u8f91\u65f6\u624d\u503c\u56de\u7968\u4ef7\u3002\\n\\n## \u4e24\u4e2a\u4e00\u8d77\u7528\u957f\u4ec0\u4e48\u6837\\n\\n\u4fdd\u7559\u4f60\u73b0\u6709\u7684 axios \u5b9e\u4f8b\u2014\u2014\u5305\u62ec\u62e6\u622a\u5668\u548c `baseURL`\u2014\u2014\u8ba9 alova \u6765\u9a71\u52a8\u5b83\uff1a\\n\\n```javascript\\nimport axios from \'axios\';\\nimport { createAlova } from \'alova\';\\nimport { axiosRequestAdapter } from \'@alova/adapter-axios\';\\nimport VueHook from \'alova/vue\';\\n\\n// \u4f60\u73b0\u6709\u7684 axios \u5b9e\u4f8b\uff0c\u4e00\u884c\u4e0d\u6539\\nconst customAxios = axios.create({ baseURL: \'/api\', timeout: 10000 });\\n\\nconst alovaInst = createAlova({\\n  statesHook: VueHook,\\n  requestAdapter: axiosRequestAdapter({ axios: customAxios })\\n});\\n```\\n\\nVue 3 \u91cc\u4e00\u4e2a\u666e\u901a\u8bf7\u6c42\u7684\u524d\u540e\u5bf9\u6bd4\uff1a\\n\\n```javascript\\n// \u53ea\u7528 axios\uff1a\u624b\u5199\u4e09\u4e2a\u72b6\u6001\\nconst loading = ref(false);\\nconst data = ref({});\\nconst error = ref(null);\\nconst load = async () => {\\n  try {\\n    loading.value = true;\\n    data.value = await customAxios.get(\'/todos\');\\n  } catch (e) {\\n    error.value = e;\\n  }\\n  loading.value = false;\\n};\\nonMounted(load);\\n\\n// axios + alova\uff1a\u72b6\u6001\u81ea\u52a8\u7ba1\u7406\\nconst { loading, data, error } = useRequest(alovaInst.Get(\'/todos\'));\\n```\\n\\n\u4f60\u4e3a axios \u505a\u7684\u914d\u7f6e\u5168\u90e8\u7ee7\u7eed\u6709\u6548\uff1amethod \u914d\u7f6e\u652f\u6301 axios \u7684\u5168\u90e8\u8bf7\u6c42\u9009\u9879\uff1b\u62e6\u622a\u5668\u987a\u5e8f\u4e5f\u662f\u786e\u5b9a\u7684\u2014\u2014alova \u7684 `beforeRequest` \u5148\u4e8e axios \u8bf7\u6c42\u62e6\u622a\u5668\u89e6\u53d1\uff0calova \u7684 `responded` \u665a\u4e8e axios \u54cd\u5e94\u62e6\u622a\u5668\u89e6\u53d1\u3002\\n\\n## \u4ec0\u4e48\u60c5\u51b5\u4e0b\u4f60\u4e0d\u9700\u8981 alova\\n\\n- \u9879\u76ee\u8bf7\u6c42\u672c\u6765\u5c31\u5c11\uff0c\u6ca1\u6709\u53cd\u590d\u51fa\u73b0\u7684\u5206\u9875/\u7f13\u5b58/\u91cd\u8bd5\u6837\u677f\u2014\u2014\u76f4\u63a5\u7528 axios \u5c31\u662f\u6b63\u786e\u9009\u62e9\u3002\\n- \u7eaf React\u3001\u7eaf Web\u3001\u4e14\u5df2\u6df1\u5ea6\u4f7f\u7528 React Query\u2014\u2014\u9664\u975e\u4f60\u9700\u8981\u8de8\u7aef\u6216\u670d\u52a1\u7aef\u7b56\u7565\uff0c\u5426\u5219\u5207\u6362\u6536\u76ca\u4e0d\u5927\u3002\\n- \u4f60\u60f3\u8981\u96f6\u62bd\u8c61\u7684\u6280\u672f\u6808\u2014\u2014alova \u7684 `Method` + hooks \u6a21\u578b\u662f\u591a\u4e00\u5c42\u6982\u5ff5\uff0c\u8fd9\u4e2a\u6210\u672c\u662f\u771f\u5b9e\u7684\u3002\\n\\n## \u4e0b\u4e00\u6b65\\n\\n- [\u4ece axios \u8fc1\u79fb](/tutorial/project/migration/from-axios)\u2014\u2014\u6e10\u8fdb\u5f0f\uff0c\u4e00\u6b21\u8fc1\u4e00\u4e2a\u63a5\u53e3\uff1b\u5b9e\u4f8b\u548c\u62e6\u622a\u5668\u539f\u6837\u4fdd\u7559\u3002\\n- [axios \u8bf7\u6c42\u9002\u914d\u5668](/resource/request-adapter/axios)\u2014\u2014\u9002\u914d\u5668\u5b8c\u6574\u9009\u9879\u3002\\n- [\u4e0e\u5176\u4ed6\u5e93\u5bf9\u6bd4](/about/comparison)\u2014\u2014react-query / swr / alova \u6a2a\u5411\u5bf9\u7167\u3002"},{"id":"/blog/uniapp-pagination","metadata":{"permalink":"/zh-CN/blog/blog/uniapp-pagination","source":"@site/i18n/zh-CN/docusaurus-plugin-content-blog/2026-07-30-uniapp-pagination.md","title":"uni-app \u5206\u9875\u5217\u8868\uff1a\u7528\u4e00\u4e2a hook \u89e3\u51b3\u7ade\u6001\u3001\u91cd\u590d\u8bf7\u6c42\u548c\u52a0\u8f7d\u72b6\u6001","description":"\u624b\u5199 uni-app \u5206\u9875\u52a0\u8f7d\u5e38\u89c1\u7684\u7ade\u6001\u3001\u91cd\u590d\u8bf7\u6c42\u3001\u8fb9\u754c\u5224\u65ad\u95ee\u9898\uff0c\u4ee5\u53ca\u5982\u4f55\u7528 alova \u7684 usePagination \u4e00\u6b21\u89e3\u51b3\u3002\u542b\u5b8c\u6574\u53ef\u8fd0\u884c\u4ee3\u7801\u4e0e\u5728\u7ebf\u793a\u4f8b\u3002","date":"2026-07-30T00:00:00.000Z","tags":[{"inline":true,"label":"uniapp","permalink":"/zh-CN/blog/tags/uniapp"},{"inline":true,"label":"\u5206\u9875","permalink":"/zh-CN/blog/tags/\u5206\u9875"},{"inline":true,"label":"usePagination","permalink":"/zh-CN/blog/tags/use-pagination"}],"readingTime":4.84,"hasTruncateMarker":false,"authors":[{"name":"Alova Team","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"/blog/uniapp-pagination","title":"uni-app \u5206\u9875\u5217\u8868\uff1a\u7528\u4e00\u4e2a hook \u89e3\u51b3\u7ade\u6001\u3001\u91cd\u590d\u8bf7\u6c42\u548c\u52a0\u8f7d\u72b6\u6001","authors":[{"name":"Alova Team"}],"tags":["uniapp","\u5206\u9875","usePagination"],"date":"2026-07-30T00:00:00.000Z","description":"\u624b\u5199 uni-app \u5206\u9875\u52a0\u8f7d\u5e38\u89c1\u7684\u7ade\u6001\u3001\u91cd\u590d\u8bf7\u6c42\u3001\u8fb9\u754c\u5224\u65ad\u95ee\u9898\uff0c\u4ee5\u53ca\u5982\u4f55\u7528 alova \u7684 usePagination \u4e00\u6b21\u89e3\u51b3\u3002\u542b\u5b8c\u6574\u53ef\u8fd0\u884c\u4ee3\u7801\u4e0e\u5728\u7ebf\u793a\u4f8b\u3002","keywords":["uniapp request pagination","uniapp \u5206\u9875\u52a0\u8f7d","uni-app \u4e0b\u62c9\u52a0\u8f7d","uni-app \u4e0a\u62c9\u52a0\u8f7d\u66f4\u591a","\u5c0f\u7a0b\u5e8f\u5206\u9875\u8bf7\u6c42","usePagination"]},"unlisted":false,"prevItem":{"title":"axios \u548c alova \u4e00\u8d77\u7528\uff0c\u8c01\u7ba1\u4ec0\u4e48","permalink":"/zh-CN/blog/compare/axios"}},"content":"\u4f60\u5927\u6982\u4e5f\u5728 uni-app \u9879\u76ee\u91cc\u5199\u8fc7\u8fd9\u6837\u7684\u5206\u9875\u52a0\u8f7d\u2014\u2014`onReachBottom` \u91cc\u52a0\u4e00\u9875\u3001\u53d1\u8bf7\u6c42\u3001\u62fc\u6570\u7ec4\uff1a\\n\\n```html\\n<script setup>\\nimport { ref } from \'vue\';\\nimport { onReachBottom, onPullDownRefresh } from \'@dcloudio/uni-app\';\\n\\nconst list = ref([]);\\nconst page = ref(1);\\nconst loading = ref(false);\\n\\nconst loadList = async () => {\\n  loading.value = true;\\n  const res = await new Promise(resolve => {\\n    uni.request({\\n      url: `https://api.example.com/goods?page=${page.value}&pageSize=10`,\\n      success: resolve\\n    });\\n  });\\n  list.value = [...list.value, ...res.data.list];\\n  loading.value = false;\\n};\\n\\nonReachBottom(() => {\\n  page.value++;\\n  loadList();\\n});\\n\\nonPullDownRefresh(async () => {\\n  page.value = 1;\\n  list.value = [];\\n  await loadList();\\n  uni.stopPullDownRefresh();\\n});\\n\\nloadList();\\n<\/script>\\n```\\n\\n\u8fd9\u6bb5\u4ee3\u7801\u80fd\u8dd1\uff0c\u4f46\u91cc\u9762\u81f3\u5c11\u57cb\u4e86 3 \u4e2a\u95ee\u9898\uff0c\u4f60\u53ef\u80fd\u5df2\u7ecf\u5728\u7ebf\u4e0a\u9047\u5230\u8fc7\u5176\u4e2d\u4e00\u4e24\u4e2a\uff1a\\n\\n1. **\u7ade\u6001**\uff1a\u7528\u6237\u5feb\u901f\u6eda\u52a8\u89e6\u53d1\u4e24\u6b21 `onReachBottom`\uff0c\u7b2c 2 \u9875\u548c\u7b2c 3 \u9875\u7684\u8bf7\u6c42\u540c\u65f6\u5728\u98de\u3002\u8c01\u5148\u56de\u6765\u8c01\u5148\u62fc\u8fdb\u6570\u7ec4\u2014\u2014\u5f31\u7f51\u4e0b\u7b2c 3 \u9875\u5b8c\u5168\u53ef\u80fd\u5148\u5230\uff0c\u5217\u8868\u987a\u5e8f\u5c31\u4e71\u4e86\u3002\\n2. **\u91cd\u590d\u8bf7\u6c42**\uff1a`onReachBottom` \u5728\u90e8\u5206\u5e73\u53f0\u4f1a\u8fde\u7eed\u89e6\u53d1\u591a\u6b21\uff0c\u6ca1\u6709\u9632\u91cd\uff0c\u540c\u4e00\u9875\u6570\u636e\u4f1a\u88ab\u8bf7\u6c42\u5e76\u62fc\u63a5\u4e24\u904d\u3002\\n3. **\u8fb9\u754c\u7f3a\u5931**\uff1a\u6ca1\u6709\\"\u662f\u4e0d\u662f\u6700\u540e\u4e00\u9875\\"\u7684\u5224\u65ad\uff0c\u6eda\u5230\u5e95\u8fd8\u5728\u53d1\u7a7a\u8bf7\u6c42\uff1b\u4e0b\u62c9\u5237\u65b0\u548c\u52a0\u8f7d\u66f4\u591a\u5171\u7528\u4e00\u4e2a `loading`\uff0c\u5237\u65b0\u65f6\u5217\u8868\u5148\u88ab\u6e05\u7a7a\u518d\u6162\u6162\u56de\u586b\uff0c\u9875\u9762\u4f1a\u95ea\u3002\\n\\n\u8981\u628a\u8fd9\u4e09\u4e2a\u5751\u90fd\u8865\u4e0a\uff0c\u8fd8\u5f97\u52a0\uff1a\u8bf7\u6c42\u53bb\u91cd\u7684\u6807\u8bb0\u4f4d\u3001\u6309\u9875\u7801\u4e22\u5f03\u8fc7\u671f\u54cd\u5e94\u3001`isLastPage` \u8ba1\u7b97\u3001\u5237\u65b0\u4e0e\u8ffd\u52a0\u4e24\u5957\u72b6\u6001\u2026\u2026\u624b\u5199\u4e0b\u6765\u901a\u5e38\u662f\u51e0\u5341\u884c\u548c\u5217\u8868\u4e1a\u52a1\u65e0\u5173\u7684\u6837\u677f\u4ee3\u7801\uff0c\u800c\u4e14\u6bcf\u4e2a\u5217\u8868\u9875\u90fd\u8981\u518d\u6765\u4e00\u904d\u3002\\n\\n## \u7406\u60f3\u7684\u5206\u9875\u65b9\u6848\u9700\u8981\u4ec0\u4e48\\n\\n\u5148\u4e0d\u8c08\u4efb\u4f55\u5e93\uff0c\u4e00\u4e2a\\"\u4e0d\u51fa\u4e8b\\"\u7684\u5206\u9875\u5b9e\u73b0\u81f3\u5c11\u8981\u5185\u5efa\u8fd9\u4e9b\u80fd\u529b\uff1a\\n\\n- **\u8bf7\u6c42\u7ea7\u53bb\u91cd**\uff1a\u540c\u53c2\u6570\u8bf7\u6c42\u5728\u98de\u65f6\u4e0d\u91cd\u53d1\uff1b\\n- **\u54cd\u5e94\u6309\u9875\u5f52\u4f4d**\uff1a\u665a\u5230\u7684\u65e7\u9875\u54cd\u5e94\u4e0d\u80fd\u8986\u76d6\u65b0\u9875\uff1b\\n- **\u8ffd\u52a0/\u5237\u65b0\u4e24\u79cd\u6a21\u5f0f**\uff1a\u52a0\u8f7d\u66f4\u591a\u662f\u8ffd\u52a0\uff0c\u4e0b\u62c9\u5237\u65b0\u662f\u91cd\u7f6e\uff1b\\n- **\u8fb9\u754c\u72b6\u6001**\uff1a`isLastPage`\u3001`total`\u3001\u52a0\u8f7d\u4e2d/\u9884\u52a0\u8f7d\u4e2d\u8981\u80fd\u76f4\u63a5\u62ff\u5230\uff1b\\n- **\u8de8\u7aef\u53ef\u7528**\uff1a\u540c\u4e00\u5957\u4ee3\u7801\u8981\u80fd\u8dd1\u5728\u5c0f\u7a0b\u5e8f\u3001H5\u3001App\u3002\\n\\n\u6700\u540e\u4e00\u70b9\u662f uni-app \u573a\u666f\u7684\u7279\u6b8a\u7ea6\u675f\u2014\u2014React Query\u3001SWR \u8fd9\u7c7b\u65b9\u6848\u9ed8\u8ba4\u9762\u5411\u6d4f\u89c8\u5668 `fetch`\uff0c\u5728\u5c0f\u7a0b\u5e8f\u73af\u5883\uff08`uni.request`\uff09\u91cc\u6ca1\u6709\u5b98\u65b9\u9002\u914d\u3002\u8fd9\u4e5f\u662f\u5f88\u591a uni-app \u9879\u76ee\u6700\u7ec8\u8fd8\u662f\u56de\u5230\u624b\u5199\u7684\u539f\u56e0\u3002\\n\\n## \u7528 usePagination \u5b9e\u73b0\\n\\n[alova](https://alova.js.org) \u662f\u4e00\u4e2a\u8bf7\u6c42\u7b56\u7565\u5e93\uff1a\u4e00\u5957\u8bf7\u6c42 API\uff0c\u8dd1\u5728 Web\u3001App\uff08uni-app/Taro\uff09\u3001\u670d\u52a1\u7aef\uff08BFF\uff09\u3002\u5b83\u901a\u8fc7 `@alova/adapter-uniapp` \u9002\u914d\u5668\u76f4\u63a5\u4f7f\u7528 `uni.request` \u53d1\u8bf7\u6c42\uff0c\u4e0a\u5c42\u7684 `usePagination` \u7b56\u7565 hook \u628a\u4e0a\u9762\u90a3\u4efd\u9700\u6c42\u6e05\u5355\u5168\u90e8\u5185\u5efa\u4e86\u3002\\n\\n\u5b89\u88c5\uff08\u6ce8\u610f\uff1auni-app \u9002\u914d\u5668\u76ee\u524d\u4ec5\u652f\u6301 Vue 3 \u7248\u672c\u7684 uni-app\uff09\uff1a\\n\\n```bash\\nnpm install alova @alova/adapter-uniapp @alova/shared --save\\n```\\n\\n\u521b\u5efa alova \u5b9e\u4f8b\uff0c\u9002\u914d\u5668\u4e00\u6b21\u6027\u63d0\u4f9b\u8bf7\u6c42\u9002\u914d\u3001\u5b58\u50a8\u9002\u914d\u548c VueHook\uff1a\\n\\n```js\\n// api/index.js\\nimport { createAlova } from \'alova\';\\nimport AdapterUniapp from \'@alova/adapter-uniapp\';\\n\\nexport const alovaInst = createAlova({\\n  baseURL: \'https://api.example.com\',\\n  ...AdapterUniapp(),\\n  responded(response) {\\n    const { statusCode, data } = response;\\n    if (statusCode >= 400) {\\n      throw new Error(\'request error\');\\n    }\\n    return data || null;\\n  }\\n});\\n```\\n\\n\u5217\u8868\u9875\u5b8c\u6574\u5b9e\u73b0\u2014\u2014\u4e4b\u524d\u624b\u5199\u7684\u9875\u7801\u7ba1\u7406\u3001\u7ade\u6001\u9632\u62a4\u3001\u8fb9\u754c\u5224\u65ad\u3001\u53cc loading\uff0c\u73b0\u5728\u90fd\u7531 hook \u8fd4\u56de\uff1a\\n\\n```html\\n<template>\\n  <view v-for=\\"item in data\\" :key=\\"item.id\\" class=\\"goods-item\\">\\n    {{ item.name }}\\n  </view>\\n  <view v-if=\\"loading\\">\u52a0\u8f7d\u4e2d...</view>\\n  <view v-if=\\"isLastPage\\">\u6ca1\u6709\u66f4\u591a\u4e86</view>\\n</template>\\n\\n<script setup>\\nimport { usePagination } from \'alova/client\';\\nimport { onReachBottom, onPullDownRefresh } from \'@dcloudio/uni-app\';\\nimport { alovaInst } from \'@/api\';\\n\\nconst queryGoods = (page, pageSize) =>\\n  alovaInst.Get(\'/goods\', {\\n    params: { page, pageSize }\\n  });\\n\\nconst { loading, data, page, isLastPage, total, reload } = usePagination(\\n  (page, pageSize) => queryGoods(page, pageSize),\\n  {\\n    append: true,        // \u8ffd\u52a0\u6a21\u5f0f\uff1a\u4e0b\u4e00\u9875\u6570\u636e\u81ea\u52a8\u62fc\u5230\u5217\u8868\u5e95\u90e8\\n    initialPageSize: 10,\\n    data: response => response.list,\\n    total: response => response.total\\n  }\\n);\\n\\n// \u52a0\u8f7d\u66f4\u591a\uff1a\u53ea\u6539\u9875\u7801\uff0c\u53bb\u91cd\u3001\u7ade\u6001\u3001\u672b\u9875\u5224\u65ad\u90fd\u5728 hook \u5185\u90e8\u5904\u7406\\nonReachBottom(() => {\\n  if (!isLastPage.value) {\\n    page.value++;\\n  }\\n});\\n\\n// \u4e0b\u62c9\u5237\u65b0\uff1areload \u91cd\u7f6e\u5230\u7b2c\u4e00\u9875\\nonPullDownRefresh(async () => {\\n  await reload();\\n  uni.stopPullDownRefresh();\\n});\\n<\/script>\\n```\\n\\n\u5bf9\u6bd4\u4e00\u4e0b\uff1a\u4e1a\u52a1\u4ee3\u7801\u53ea\u5269\\"\u9875\u7801 +1\\"\u548c\\"reload\\"\u4e24\u4e2a\u52a8\u4f5c\uff0c\u4e4b\u524d\u90a3 3 \u4e2a\u5751\u5bf9\u5e94\u7684\u9632\u62a4\u903b\u8f91\uff08\u8bf7\u6c42\u5171\u4eab\u53bb\u91cd\u3001\u54cd\u5e94\u5f52\u4f4d\u3001`isLastPage`\uff09\u90fd\u4e0d\u9700\u8981\u4f60\u81ea\u5df1\u7ef4\u62a4\u3002`usePagination` \u8fd8\u9ed8\u8ba4\u5f00\u542f\u76f8\u90bb\u9875\u9884\u52a0\u8f7d\uff0c\u7ffb\u9875\u65f6\u4e0b\u4e00\u9875\u5f80\u5f80\u5df2\u7ecf\u5728\u7f13\u5b58\u91cc\u3002\\n\\n\u540c\u4e00\u4efd\u4ee3\u7801\u7f16\u8bd1\u5230\u5fae\u4fe1\u5c0f\u7a0b\u5e8f\u3001H5\u3001App \u5747\u53ef\u8fd0\u884c\u2014\u2014\u53d1\u8bf7\u6c42\u7684\u59cb\u7ec8\u662f `uni.request`\uff0calova \u53ea\u8d1f\u8d23\\"\u600e\u4e48\u8bf7\u6c42\\"\u8fd9\u4e00\u5c42\u3002\u5982\u679c\u4f60\u7684\u9879\u76ee\u5df2\u7ecf\u5728\u7528 axios\uff08H5 \u7aef\uff09\uff0c\u5b83\u540c\u6837\u53ef\u4ee5\u901a\u8fc7 `@alova/adapter-axios` \u4f5c\u4e3a alova \u7684\u8bf7\u6c42\u9002\u914d\u5668\u7ee7\u7eed\u5de5\u4f5c\uff0c\u62e6\u622a\u5668\u903b\u8f91\u4e0d\u7528\u52a8\u3002\\n\\n\u5728\u7ebf\u793a\u4f8b\uff08\u542b\u5206\u9875\u3001\u4e0b\u62c9\u52a0\u8f7d\u7b49 24+ \u4e2a\u53ef\u8fd0\u884c\u4f8b\u5b50\uff09\uff1a[alova.js.org/examples](https://alova.js.org/examples/)\\n\\n## \u4ec0\u4e48\u60c5\u51b5\u4e0b\u4f60\u4e0d\u9700\u8981\u5b83\\n\\n\u8bda\u5b9e\u5730\u8bf4\uff0c\u4ee5\u4e0b\u573a\u666f\u624b\u5199\u5c31\u591f\u4e86\uff0c\u5f15\u5165\u4efb\u4f55\u8bf7\u6c42\u5e93\u90fd\u662f\u591a\u4f59\uff1a\\n\\n- **\u5217\u8868\u53ea\u6709\u4e00\u9875\u3001\u6216\u6570\u636e\u91cf\u56fa\u5b9a**\uff1a\u4e00\u4e2a `uni.request` \u52a0\u4e00\u4e2a `ref` \u5c31\u662f\u6700\u4f18\u89e3\u3002\\n- **\u9879\u76ee\u53ea\u8dd1 H5 \u4e14\u5df2\u6df1\u5ea6\u4f7f\u7528 React Query/SWR**\uff1a\u5b83\u4eec\u5728\u7eaf\u6d4f\u89c8\u5668\u73af\u5883\u5f88\u6210\u719f\uff0c\u6ca1\u5fc5\u8981\u4e3a\u5355\u7aef\u9879\u76ee\u6362\u65b9\u6848\u3002\\n- **uni-app Vue 2 \u9879\u76ee**\uff1a`@alova/adapter-uniapp` \u4ec5\u652f\u6301 Vue 3\uff0cVue 2 \u9879\u76ee\u8bf7\u8bc4\u4f30\u540e\u518d\u5f15\u5165\u3002\\n- **\u56e2\u961f\u5df2\u6709\u7a33\u5b9a\u7684\u5206\u9875\u5c01\u88c5\u4e14\u7ecf\u8fc7\u7ebf\u4e0a\u9a8c\u8bc1**\uff1a\u80fd\u8dd1\u7684\u8001\u4ee3\u7801\u6bd4\u65b0\u4f9d\u8d56\u66f4\u53ef\u9760\uff0c\u7b49\u91cd\u6784\u7a97\u53e3\u518d\u8bf4\u3002\\n\\n\u53cd\u8fc7\u6765\uff0c\u5982\u679c\u4f60\u7684\u9879\u76ee\u91cc\u6709\u591a\u4e2a\u5206\u9875/\u4e0b\u62c9\u52a0\u8f7d\u5217\u8868\u3001\u8e29\u8fc7\u7ade\u6001\u6216\u91cd\u590d\u8bf7\u6c42\u7684\u7ebf\u4e0a\u95ee\u9898\u3001\u6216\u8005\u8981\u540c\u65f6\u7ef4\u62a4\u5c0f\u7a0b\u5e8f + H5 + App \u4e09\u7aef\uff0c`usePagination` \u503c\u5f97\u8bd5\u4e00\u6b21\uff1a\\n\\n```bash\\nnpm i alova\\n```"}]}}')}}]);